def nextGreaterElement(nums):
    result = [-1] * len(nums)
    stack = []  # stores indexes

    for i in range(len(nums)):
        # Pop all indexes whose answer is nums[i]
        while stack and nums[i] > nums[stack[-1]]:
            index = stack.pop()
            result[index] = nums[i]
        stack.append(i)

    return result
